<?php
declare(strict_types=1);
namespace OCA\FilzmannPermissionMatrix\PublicApi\V1 {
 interface PermissionProvider{public function descriptor():PermissionProviderDescriptor;public function collect():PermissionProviderResult;} final class PermissionProviderDescriptor{public function __construct(...$a){}} final class PermissionCondition{private function __construct(public string $operator,public array $children=[]){}public static function authenticated():self{return new self('authenticated');}public static function self():self{return new self('self');}public static function nextcloudAdmin():self{return new self('nextcloud-admin');}public static function temporaryAppAdminGrant():self{return new self('app-admin-grant');}public static function all(array $children):self{return new self('all',$children);}} final class PermissionRule{public function __construct(public string $type,public string $name,public string $detail,public string $permission,public string $label,public string $effect,public string $scope,public PermissionCondition $condition,public string $source,public string $confidence){}} final class PermissionProviderResult{public function __construct(public array $rules,public bool $complete=true,public array $warnings=[]){}} final class RegisterPermissionProvidersEvent{public array $providers=[];public function register(PermissionProvider $p):void{$this->providers[]=$p;}}
}
namespace { use OCA\AdRoom\Permission\RoomPermissionProvider;use OCA\AdRoom\Permission\RoomPermissionProviderListener;use OCA\FilzmannPermissionMatrix\PublicApi\V1\RegisterPermissionProvidersEvent;$provider=new RoomPermissionProvider();$rules=$provider->collect()->rules;$map=[];foreach($rules as $r)$map[$r->permission]=$r->condition->operator;if($map!==['room.read'=>'authenticated','booking.manage-own'=>'self','booking.manage-all'=>'all','room.manage'=>'all'])throw new RuntimeException('Der Raumrechtevertrag muss native Administration und aktive app-lokale Freigabe gemeinsam verlangen.');foreach(array_slice($rules,2) as $rule)if(array_map(fn($child)=>$child->operator,$rule->condition->children)!==['nextcloud-admin','app-admin-grant'])throw new RuntimeException('Die zeitgebundene Adminbedingung ist unvollständig.');$event=new RegisterPermissionProvidersEvent();(new RoomPermissionProviderListener($provider))->handle($event);if(($event->providers[0]??null)!==$provider)throw new RuntimeException('Lazy-Registrierung fehlt.');echo "Room permission provider tests passed\n";}
